<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Composition with Red, Blue and Yellow (1930) — Piet Mondrian</title>
<meta name="description" content="Piet Mondrian, Composition with Red, Blue and Yellow, 1930. De Stijl, Neoplasticism, and why asymmetric balance of a few primary-colour blocks still matters.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Jost:wght@400;500;700;900&display=swap" rel="stylesheet">
<style>
:root{--red:#d6221c;--blue:#154a9c;--yellow:#f6cf1a;--white:#f7f5ee;--black:#111;--grey:#cfcfca;--line:clamp(6px,1vw,12px)}
*{box-sizing:border-box;margin:0}
html{background:var(--black)}
body{font-family:"Jost","Futura","Century Gothic",Arial,sans-serif;color:var(--black);background:var(--black);line-height:1.5;font-size:clamp(1rem,1.1vw + .6rem,1.2rem)}
a{color:inherit}
:focus-visible{outline:4px solid var(--black);outline-offset:3px}
.skip{position:absolute;left:-999px}.skip:focus{left:8px;top:8px;background:var(--yellow);padding:.5rem;z-index:9}
/* The grid: cells separated by thick black lines (gap shows the black body) */
main{display:grid;gap:var(--line);padding:var(--line);min-height:100vh;
 grid-template-columns:minmax(0,1fr) minmax(0,1.4fr) minmax(0,.7fr);
 grid-template-rows:auto auto auto auto;
 grid-template-areas:
  "title title red"
  "year  story red"
  "move  story why"
  "blue  src   yellow";}
.cell{background:var(--white);padding:clamp(1rem,2.5vw,2.2rem);position:relative}
.title{grid-area:title;display:flex;flex-direction:column;justify-content:flex-end;min-height:34vh}
.red{grid-area:red;background:var(--red);min-height:16rem}
.year{grid-area:year;display:flex;flex-direction:column;justify-content:space-between}
.story{grid-area:story}
.move{grid-area:move}
.why{grid-area:why;background:var(--grey)}
.blue{grid-area:blue;background:var(--blue);min-height:7rem}
.src{grid-area:src;display:flex;flex-direction:column;justify-content:center;gap:1rem}
.yellow{grid-area:yellow;background:var(--yellow);min-height:7rem;display:flex;align-items:flex-end}
.eyebrow{font-weight:700;letter-spacing:.2em;text-transform:uppercase;font-size:.75rem;margin-bottom:.6rem}
h1{font-weight:900;text-transform:uppercase;line-height:.92;font-size:clamp(2.2rem,6.5vw,5.6rem);letter-spacing:-.01em}
h1 span{display:block}
h1 .r{color:var(--red)}h1 .b{color:var(--blue)}
h1 .y{background:var(--yellow);display:inline-block;padding:0 .12em;width:max-content}
.by{margin-top:1.2rem;font-weight:500}
.big{font-weight:900;font-size:clamp(3.5rem,9vw,7.5rem);line-height:.9;letter-spacing:-.03em}
h2{font-weight:900;text-transform:uppercase;font-size:1.35rem;line-height:1.1;margin-bottom:.8rem}
p+p{margin-top:.8rem}
ul{padding-left:1.1rem}li+li{margin-top:.35rem}
.lead{font-size:1.15em;font-weight:500}
.cta{display:inline-block;align-self:flex-start;background:var(--black);color:var(--white);text-decoration:none;font-weight:700;text-transform:uppercase;letter-spacing:.08em;padding:.9rem 1.4rem;border:0;transition:background .15s,color .15s}
.cta:hover{background:var(--red)}
.cta:focus-visible{outline-color:var(--blue)}
.small{font-size:.85rem}
.chips{display:flex;gap:.5rem;margin-top:1rem}.chips i{width:1.6rem;height:1.6rem;border:3px solid var(--black);display:block}
.yellow span{font-weight:700;font-size:.8rem;letter-spacing:.12em;text-transform:uppercase}
@media (prefers-reduced-motion:no-preference){
 .red,.blue,.yellow{animation:in .8s cubic-bezier(.2,.7,.2,1) both}
 .blue{animation-delay:.15s}.yellow{animation-delay:.3s}
 @keyframes in{from{transform:scaleY(0);transform-origin:top}to{transform:none}}
}
@media (max-width:760px){
 main{grid-template-columns:1fr 1fr;
  grid-template-areas:"title title" "year year" "story story" "move move" "why why" "src src" "red red" "blue yellow"}
 .red{min-height:12rem}
}
